/**
 * Jemlit's mystery box, copied from the live site (captured 14 October 2026).
 *
 * One open, as Jemlit publishes it on /en/provably-fair/algorithm:
 *   - the server seed is a random string; its SHA-512 hash is shown before play;
 *   - the client seed is generated by the browser and may be changed by the player;
 *   - the nonce starts at 1 and increases by 1 with every play under the same server seed;
 *   - digest = HMAC-SHA512/256(key = serverSeed, data = clientSeed + "-" + nonce);
 *   - roll = hexdec(digest) / 16^64 × 100, a number from 0 to 100;
 *   - the item whose band satisfies lower < roll ≤ upper wins (bands are listed on the box page, "See rolls").
 * The engine reproduces Jemlit's own published example (digest 38611068…, roll 22.0231).
 *
 * Payouts: an item is shipped, or exchanged for Credits at its "cashback" (the page lists it per item, mostly 90% of
 * the listed price). Some rows are credit only (auto cashback). Credits buy boxes and games and never become money.
 */
import { hmacSha512_256Hex, sha512Hex, sha256Hex, canonicalJson } from "../hash";
import { chiSquare } from "../metrics";
import { makeRng, type Rng } from "../rng";
import { JEMLIT_FEATURED } from "../jemlitLive.generated";
import type { JemlitBox, JemlitConfig, JemlitItem, JemlitItemStat, JemlitPlayerStat, JemlitResult, JemlitSpin, Progress, Verifier } from "../types";

export const JEMLIT_FEATURED_BY_SLUG = new Map(JEMLIT_FEATURED.map((b) => [b.slug, b] as const));

/** The box a config refers to: the one carried in the config (loaded or built), else a featured box. */
export function jemlitBoxOf(cfg: Pick<JemlitConfig, "boxSlug" | "box">): JemlitBox {
  if (cfg.box && cfg.box.slug === cfg.boxSlug) return cfg.box;
  const b = JEMLIT_FEATURED_BY_SLUG.get(cfg.boxSlug);
  if (!b) throw new Error(`Jemlit box not loaded: ${cfg.boxSlug}`);
  return b;
}

export function liveChances(box: JemlitBox): Record<string, number> {
  return Object.fromEntries(box.items.map((i) => [i.id, i.chance]));
}

export interface JemlitBand {
  item: JemlitItem;
  chance: number;
  /** on a 0 to 100 line */
  lower: number;
  upper: number;
}
export interface JemlitTable {
  bands: JemlitBand[];
  total: number;
  hash: string;
}

/** Bands in stored order from the chances (the live page lists outcome_from/outcome_to; they are the running sum). */
export function buildBands(box: JemlitBox, chances?: Record<string, number>): JemlitTable {
  let acc = 0;
  const bands = box.items.map((it) => {
    const chance = Math.max(0, chances?.[it.id] ?? it.chance);
    const lower = acc * 100;
    acc += chance;
    return { item: it, chance, lower, upper: acc * 100 };
  });
  const hash = sha256Hex(canonicalJson({ slug: box.slug, price: box.price, table: bands.map((b) => ({ id: b.item.id, chance: b.chance })) }));
  return { bands, total: acc, hash };
}

/** Jemlit's rule: lower < roll ≤ upper. The roll is scaled to the table total so an edited table still resolves. */
export function lookupBand(table: JemlitTable, roll: number): JemlitBand {
  const r = table.total > 0 ? (roll / 100) * table.total * 100 : roll;
  for (const b of table.bands) if (b.chance > 0 && r > b.lower && r <= b.upper) return b;
  if (r <= 0) for (const b of table.bands) if (b.chance > 0) return b;
  for (let i = table.bands.length - 1; i >= 0; i--) if (table.bands[i].chance > 0) return table.bands[i];
  return table.bands[table.bands.length - 1];
}

export interface JemlitValues {
  /** what one Credit counts for on screen ($1: Credits are spent 1:1 on box prices) */
  creditFace: number;
  /** what a Credit really costs the operator when it only buys more boxes */
  creditReal: number;
  /** fraction of the listed price a shipped item is really worth */
  itemRealized: number;
}
export interface JemlitItemMath {
  id: string;
  label: string;
  credit: boolean;
  chance: number;
  share: number;
  oneIn: number;
  price: number;
  cashback: number;
  costPrice: number;
  costCashback: number;
  costReal: number;
}
export interface JemlitMath {
  total: number;
  pShipItem: number;
  pAtOrAbovePrice: number;
  evPrice: number;
  evCashback: number;
  evReal: number;
  returnPrice: number;
  returnCashback: number;
  returnReal: number;
  perItem: JemlitItemMath[];
}

/** What the table pays per open: at listed prices, in cashback Credits, and in real money (credit rows at creditReal, shipped items at itemRealized × price). */
export function jemlitMath(box: JemlitBox, chances: Record<string, number> | undefined, v: JemlitValues): JemlitMath {
  const t = buildBands(box, chances);
  let pShip = 0;
  let pOver = 0;
  let evPrice = 0;
  let evCash = 0;
  let evReal = 0;
  const perItem = t.bands.map((b) => {
    const share = t.total > 0 ? b.chance / t.total : 0;
    const credit = b.item.autoCashback || !b.item.shippable;
    const real = credit ? b.item.cashback * v.creditReal : b.item.price * v.itemRealized;
    if (!credit) pShip += share;
    if (b.item.price >= box.price) pOver += share;
    evPrice += share * b.item.price;
    evCash += share * b.item.cashback;
    evReal += share * real;
    return { id: b.item.id, label: b.item.label, credit, chance: b.chance, share, oneIn: share > 0 ? 1 / share : Infinity, price: b.item.price, cashback: b.item.cashback, costPrice: share * b.item.price, costCashback: share * b.item.cashback, costReal: share * real };
  });
  const p = box.price || 1;
  return { total: t.total, pShipItem: pShip, pAtOrAbovePrice: pOver, evPrice, evCashback: evCash, evReal, returnPrice: evPrice / p, returnCashback: evCash / p, returnReal: evReal / p, perItem };
}

export function normaliseChances(box: JemlitBox, chances: Record<string, number>): Record<string, number> {
  const total = box.items.reduce((s, i) => s + Math.max(0, chances[i.id] ?? i.chance), 0);
  if (total <= 0) return liveChances(box);
  return Object.fromEntries(box.items.map((i) => [i.id, Math.max(0, chances[i.id] ?? i.chance) / total]));
}

/** Multiply the chance of every item worth at least the box price by m; the cheap rows absorb the difference. */
export function scaleBigOdds(box: JemlitBox, base: Record<string, number>, m: number): Record<string, number> {
  const w = (i: JemlitItem) => Math.max(0, base[i.id] ?? i.chance);
  const big = box.items.filter((i) => i.price >= box.price);
  const rest = box.items.filter((i) => i.price < box.price);
  const total = box.items.reduce((s, i) => s + w(i), 0);
  const bigSum = big.reduce((s, i) => s + w(i), 0);
  const restSum = rest.reduce((s, i) => s + w(i), 0);
  const newBig = Math.min(bigSum * Math.max(0, m), total * 0.99);
  const mb = bigSum > 0 ? newBig / bigSum : 0;
  const mr = restSum > 0 ? (total - newBig) / restSum : 0;
  const out: Record<string, number> = {};
  for (const i of big) out[i.id] = w(i) * mb;
  for (const i of rest) out[i.id] = w(i) * mr;
  return out;
}

export function bigOddsRatio(box: JemlitBox, base: Record<string, number>, player?: Record<string, number>): number {
  if (!player) return 1;
  const big = box.items.filter((i) => i.price >= box.price);
  const a = big.reduce((s, i) => s + Math.max(0, base[i.id] ?? i.chance), 0);
  const b = big.reduce((s, i) => s + Math.max(0, player[i.id] ?? base[i.id] ?? i.chance), 0);
  return a > 0 ? b / a : 1;
}

/** Fit the chances of the items worth at least the price so the box returns the target share at listed prices. */
export function fitBigOdds(box: JemlitBox, base: Record<string, number>, target: number, v: JemlitValues): Record<string, number> {
  const ret = (m: number) => jemlitMath(box, scaleBigOdds(box, base, m), v).returnPrice;
  const increasing = ret(2) >= ret(0.5);
  let lo = 0;
  let hi = 1;
  const below = (m: number) => (increasing ? ret(m) < target : ret(m) > target);
  let guard = 0;
  while (below(hi) && hi < 1e6 && guard++ < 40) hi *= 2;
  for (let i = 0; i < 60; i++) {
    const mid = (lo + hi) / 2;
    if (below(mid)) lo = mid;
    else hi = mid;
  }
  return scaleBigOdds(box, base, hi);
}

/* ---------- the published recipe ---------- */
const SIXTEEN_64 = 2 ** 256;
export const jemlitDigest = (serverSeed: string, clientSeed: string, nonce: number): string => hmacSha512_256Hex(serverSeed, `${clientSeed}-${nonce}`);
/** hexdec(digest) / 16^64 × 100: a number from 0 to 100. Computed with BigInt so all 256 bits count. */
export function jemlitRoll(digest: string): number {
  const big = BigInt("0x" + digest.slice(0, 64));
  return (Number((big * 10n ** 15n) / BigInt(2) ** 256n) / 1e15) * 100;
}
export const jemlitCommit = (serverSeed: string): string => sha512Hex(serverSeed);

export function playerChances(cfg: JemlitConfig, playerId: string): Record<string, number> {
  const p = cfg.players.find((x) => x.id === playerId);
  return p?.chances ? { ...cfg.chances, ...p.chances } : cfg.chances;
}

/** One Jemlit box, opened the way the site describes: one server seed, a client seed, a nonce that counts up. */
export class JemlitOpener {
  readonly box: JemlitBox;
  private rng: Rng;
  private serverSeed: string;
  private nonce = 0;
  private tables = new Map<string, JemlitTable>();

  constructor(
    readonly cfg: JemlitConfig,
    seedLabel: string | number,
  ) {
    this.box = jemlitBoxOf(cfg);
    this.rng = makeRng("sfc32", `jemlit:${cfg.boxSlug}:${seedLabel}`);
    this.serverSeed = this.rng.hex(32);
  }
  /** The SHA-512 hash of the current server seed, shown before play. */
  get commitment(): string {
    return this.cfg.provablyFair ? jemlitCommit(this.serverSeed) : "";
  }
  get nextNonce(): number {
    return this.nonce + 1;
  }
  get opens(): number {
    return this.nonce;
  }
  /** Jemlit rotates the server seed only when the player asks (or on retirement); the nonce restarts at 1. */
  rotate(): void {
    this.serverSeed = this.rng.hex(32);
    this.nonce = 0;
  }
  tableFor(playerId: string): JemlitTable {
    let t = this.tables.get(playerId);
    if (!t) {
      t = buildBands(this.box, playerChances(this.cfg, playerId));
      this.tables.set(playerId, t);
    }
    return t;
  }
  spin(playerId: string = this.cfg.activePlayerId): JemlitSpin {
    const table = this.tableFor(playerId);
    const pf = this.cfg.provablyFair;
    this.nonce++;
    const clientSeed = pf ? this.cfg.clientSeed || "browser-generated-seed" : "";
    const digest = pf ? jemlitDigest(this.serverSeed, clientSeed, this.nonce) : "";
    const roll = pf ? jemlitRoll(digest) : this.rng.next() * 100;
    const b = lookupBand(table, roll);
    const it = b.item;
    const credit = it.autoCashback || !it.shippable;
    return {
      idx: this.nonce,
      playerId,
      boxSlug: this.box.slug,
      price: this.box.price,
      serverSeed: pf ? this.serverSeed : "",
      serverHash: pf ? jemlitCommit(this.serverSeed) : "",
      clientSeed,
      nonce: this.nonce,
      digest,
      roll,
      tableHash: table.hash,
      itemId: it.id,
      label: it.label,
      itemPrice: it.price,
      cashback: it.cashback,
      credit,
      lower: b.lower,
      upper: b.upper,
    };
  }
}

/** Recompute an open from what the player was shown. */
export function verifyJemlitSpin(spin: JemlitSpin, cfg: JemlitConfig): { ok: boolean; reason?: string } {
  if (!cfg.provablyFair || !spin.serverHash) return { ok: false, reason: "no commitment: nothing to check" };
  const box = jemlitBoxOf(cfg);
  if (jemlitCommit(spin.serverSeed) !== spin.serverHash) return { ok: false, reason: "server seed does not match the hash shown before play" };
  const table = buildBands(box, playerChances(cfg, spin.playerId));
  if (table.hash !== spin.tableHash) return { ok: false, reason: "odds table differs from the one used" };
  const digest = jemlitDigest(spin.serverSeed, spin.clientSeed, spin.nonce);
  if (digest !== spin.digest) return { ok: false, reason: "digest differs" };
  if (lookupBand(table, jemlitRoll(digest)).item.id !== spin.itemId) return { ok: false, reason: "roll lands on a different item" };
  return { ok: true };
}

export function runJemlit(cfg: JemlitConfig, seed: number, onProgress?: Progress): JemlitResult {
  const t0 = Date.now();
  const box = jemlitBoxOf(cfg);
  const opener = new JemlitOpener(cfg, seed);
  const pick = makeRng("sfc32", `jemlit-players:${seed}`);
  const players = cfg.players.length ? cfg.players : [{ id: "guest", name: "Guest", share: 1 }];
  const shareTotal = players.reduce((s, p) => s + Math.max(0, p.share), 0) || 1;
  const N = Math.max(1, Math.floor(cfg.run.opens));
  const counts = new Map<string, number>(box.items.map((i) => [i.id, 0]));
  const maths = new Map<string, JemlitMath>();
  const per = new Map<string, JemlitPlayerStat>();
  for (const p of players) {
    const m = jemlitMath(box, playerChances(cfg, p.id), cfg);
    maths.set(p.id, m);
    per.set(p.id, { id: p.id, name: p.name, opens: 0, spent: 0, items: 0, itemValue: 0, credits: 0, returnPrice: 0, expectedPrice: m.returnPrice, bigChance: m.pAtOrAbovePrice });
  }
  const sample: JemlitSpin[] = [];
  let items = 0;
  let itemValue = 0;
  let credits = 0;
  let creditOpens = 0;
  let bigWins = 0;
  let cumPrice = 0;
  let cumReal = 0;
  let dry = 0;
  let longestDry = 0;
  const curveStep = Math.max(1, Math.floor(N / 200));
  const curve: { n: number; price: number; real: number }[] = [];
  for (let i = 0; i < N; i++) {
    let r = pick.next() * shareTotal;
    let p = players[players.length - 1];
    for (const c of players) {
      r -= Math.max(0, c.share);
      if (r < 0) {
        p = c;
        break;
      }
    }
    const s = opener.spin(p.id);
    counts.set(s.itemId, (counts.get(s.itemId) ?? 0) + 1);
    const ps = per.get(p.id)!;
    ps.opens++;
    ps.spent += box.price;
    if (s.credit) {
      credits += s.cashback;
      creditOpens++;
      ps.credits += s.cashback;
    } else {
      items++;
      itemValue += s.itemPrice;
      ps.items++;
      ps.itemValue += s.itemPrice;
    }
    if (s.itemPrice >= box.price) {
      bigWins++;
      dry = 0;
    } else if (++dry > longestDry) longestDry = dry;
    cumPrice += s.itemPrice;
    cumReal += s.credit ? s.cashback * cfg.creditReal : s.itemPrice * cfg.itemRealized;
    if ((i + 1) % curveStep === 0 || i === N - 1) curve.push({ n: i + 1, price: cumPrice / ((i + 1) * box.price || 1), real: cumReal / ((i + 1) * box.price || 1) });
    if (sample.length < cfg.run.verifySample) sample.push(s);
    if (onProgress && (i & 1023) === 0) onProgress(i, N);
  }
  const base = jemlitMath(box, cfg.chances, cfg);
  const byItem: JemlitItemStat[] = box.items.map((it) => {
    let expected = 0;
    for (const p of players) {
      const pi = maths.get(p.id)!.perItem.find((x) => x.id === it.id)!;
      expected += pi.share * per.get(p.id)!.opens;
    }
    const b = base.perItem.find((x) => x.id === it.id)!;
    return { id: it.id, label: it.label, credit: b.credit, chance: b.chance, price: it.price, cashback: it.cashback, expected, actual: counts.get(it.id) ?? 0, costPerOpen: b.costPrice };
  });
  const chi = chiSquare(
    byItem.map((b) => b.actual),
    byItem.map((b) => b.expected),
  );
  const spent = N * box.price;
  const verifier: Verifier = { sampled: 0, passed: 0, failed: 0, reasons: {} };
  for (const s of sample) {
    verifier.sampled++;
    const v = verifyJemlitSpin(s, cfg);
    s.verified = v.ok;
    if (v.ok) verifier.passed++;
    else {
      verifier.failed++;
      const k = v.reason ?? "unknown";
      verifier.reasons[k] = (verifier.reasons[k] ?? 0) + 1;
    }
  }
  const perPlayer = [...per.values()].map((p) => ({ ...p, returnPrice: p.spent > 0 ? (p.itemValue + p.credits) / p.spent : 0 }));
  onProgress?.(N, N);
  return {
    kind: "jemlit",
    boxSlug: box.slug,
    boxName: box.name,
    price: box.price,
    opens: N,
    spent,
    items,
    itemValue,
    itemValueReal: itemValue * cfg.itemRealized,
    credits,
    creditOpens,
    bigWins,
    returnPrice: spent > 0 ? cumPrice / spent : 0,
    returnReal: spent > 0 ? cumReal / spent : 0,
    expectedPrice: base.returnPrice,
    expectedCashback: base.returnCashback,
    expectedReal: base.returnReal,
    pBig: base.pAtOrAbovePrice,
    byItem,
    chi,
    perPlayer,
    verifier,
    sample,
    curve,
    longestDry,
    elapsedMs: Date.now() - t0,
  };
}
